/**
 * Walks every live organization, one keyset page at a time, so a sweep covers
 * the whole tenant base no matter how many there are.
 */
import * as orgRepo from "@/server/repositories/organization-repository";
import type { OrgId } from "@/types/common";

export async function* eachLiveOrgId(
  batchSize: number,
): AsyncGenerator<OrgId> {
  let afterId: OrgId | null = null;

  for (;;) {
    const page = await orgRepo.listLiveOrgIds(afterId, batchSize);
    for (const orgId of page) yield orgId;

    if (page.length < batchSize) return;
    afterId = page[page.length - 1] ?? null;
  }
}
EOF

